using UserDaoCreator = std::function<std::unique_ptr<UserDao>(Db&)>;

const std::unordered_map<std::string_view, UserDaoCreator> CREATORS = {
    { "pg",     [](Db& db) -> std::unique_ptr<UserDao> { return std::make_unique<PgUserDao>(db); } },
    { "sqlite", [](Db& db) -> std::unique_ptr<UserDao> { return std::make_unique<SqliteUserDao>(db); } },
};

std::unique_ptr<UserDao> make_user_dao(std::string_view store, Db& db) {
    auto it = CREATORS.find(store);
    if (it == CREATORS.end()) throw std::invalid_argument("unknown store");
    return it->second(db);
}

